func (s Spec) Validate() error {
	if !strings.HasPrefix(s.SecurityListID, "ocid1.securitylist.") {
		return errors.New("security list spec requires a security list OCID")
	}
	counts := map[string]int{}
	seen := map[string]bool{}
	for _, rule := range s.Rules {
		if err := rule.Validate(); err != nil {
			return err
		}
		if rule.EffectivePeerType() == nsg.PeerNSG {
			return errors.New("security list rules cannot name an NSG peer")
		}
		if seen[rule.Identity()] {
			return errors.New("security list spec repeats a rule")
		}
		seen[rule.Identity()] = true
		counts[rule.Direction]++
	}
	for direction, count := range counts {
		if count > maxRulesPerDirection {
			return fmt.Errorf("security list spec has %d %s rules, more than OCI's %d", count, direction, maxRulesPerDirection)
		}
	}
	if !s.AllowEmpty && (counts[nsg.DirectionIngress] == 0 || counts[nsg.DirectionEgress] == 0) {
		return errors.New("security list spec leaves a direction empty without allowEmpty")
	}
	return nil
}

func (Reconciler) Kind() string { return Kind }

func (r Reconciler) Observe(ctx context.Context, target ociresource.Target[Spec]) (List, bool, error) {
	if err := target.Spec.Validate(); err != nil {
		return List{}, false, err
	}
	if target.Deleting {
		// Deletion relinquishes management and never strips the list.
		return List{}, false, nil
	}
	list, err := r.API.GetList(ctx, target.Spec.SecurityListID)
	if err != nil {
		return List{}, false, err
	}
	if list.ID != target.Spec.SecurityListID || !target.Ownership.Owns(target.Key, list.Tags) {
		return List{}, true, ociresource.ErrForeign
	}
	return list, true, nil
}

func identities(rules []nsg.Rule) []string {
	out := make([]string, 0, len(rules))
	for _, rule := range rules {
		out = append(out, rule.Identity())
	}
	slices.Sort(out)
	return out
}

func (Reconciler) Diff(target ociresource.Target[Spec], observed List, found bool) ociresource.Plan {
	var plan ociresource.Plan
	if !found {
		plan.Add("blocked", "security list %s is not visible", target.Spec.SecurityListID)
		return plan
	}
	want, have := identities(target.Spec.Rules), identities(observed.Rules)
	for _, identity := range want {
		if _, ok := slices.BinarySearch(have, identity); !ok {
			plan.Add("add-rule", "%s", identity)
		}
	}
	for index, identity := range have {
		if _, ok := slices.BinarySearch(want, identity); !ok || index > 0 && have[index-1] == identity {
			plan.Add("remove-rule", "%s", identity)
		}
	}
	if target.Ownership.Stale(observed.Tags, target.Generation, target.SpecDigest) {
		plan.Add("tag", "restamp ownership generation %d", target.Generation)
	}
	return plan
}

// Apply writes the whole desired rule set and the restamped ownership tags in
// one If-Match update, so a concurrent out-of-band edit fails the write
// instead of being overwritten blind.
func (r Reconciler) Apply(ctx context.Context, target ociresource.Target[Spec], observed List, found bool, _ ociresource.Plan) error {
	if !found {
		return fmt.Errorf("security list %s is not visible; the reconciler never creates lists", target.Spec.SecurityListID)
	}
	if observed.ETag == "" {
		return errors.New("security list has no ETag; refusing an unconditional replace")
	}
	tags := observed.Tags.Merge(target.Ownership.Stamp(target.Key, target.Generation, target.SpecDigest))
	if err := target.Fence(ctx); err != nil {
		return err
	}
	if err := r.API.UpdateList(ctx, target.Spec.SecurityListID, observed.ETag, slices.Clone(target.Spec.Rules), tags); err != nil {
		return fmt.Errorf("replace security list rules: %w", err)
	}
	return nil
}

// Delete is never reached: Observe reports a tombstoned list as not found so
// the record is purged without touching the cloud.
func (Reconciler) Delete(context.Context, ociresource.Target[Spec], List) error { return nil }

func newSDKAPI(factory *ociclient.Factory, endpoint string) (API, error) {
	network, err := factory.Network()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&network.BaseClient, endpoint)
	return sdkAPI{network: network}, nil
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func ingressRule(rule core.IngressSecurityRule) nsg.Rule {
	normalized := nsg.Rule{Direction: nsg.DirectionIngress, Protocol: deref(rule.Protocol), Peer: deref(rule.Source),
		PeerType: string(rule.SourceType), Stateless: rule.IsStateless != nil && *rule.IsStateless,
		Description: deref(rule.Description)}
	return finish(normalized, rule.TcpOptions, rule.UdpOptions, rule.IcmpOptions != nil)
}

func egressRule(rule core.EgressSecurityRule) nsg.Rule {
	normalized := nsg.Rule{Direction: nsg.DirectionEgress, Protocol: deref(rule.Protocol), Peer: deref(rule.Destination),
		PeerType: string(rule.DestinationType), Stateless: rule.IsStateless != nil && *rule.IsStateless,
		Description: deref(rule.Description)}
	return finish(normalized, rule.TcpOptions, rule.UdpOptions, rule.IcmpOptions != nil)
}

func finish(rule nsg.Rule, tcp *core.TcpOptions, udp *core.UdpOptions, icmp bool) nsg.Rule {
	if rule.PeerType == nsg.PeerCIDR {
		rule.PeerType = ""
	}
	low, high, ok := nsg.PortRange(tcp, udp)
	rule.PortMin, rule.PortMax = low, high
	if !ok || icmp {
		rule = rule.MarkUnsupported()
	}
	return rule
}

func (a sdkAPI) GetList(ctx context.Context, id string) (List, error) {
	response, err := a.network.GetSecurityList(ociclient.RequestContext(ctx), core.GetSecurityListRequest{SecurityListId: new(id)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return List{}, fmt.Errorf("get OCI security list: %w: %w", ociresource.ErrGone, err)
		}
		return List{}, fmt.Errorf("get OCI security list: %w", err)
	}
	list := List{ID: deref(response.Id), ETag: deref(response.Etag),
		Tags: ociresource.Tags{Freeform: response.FreeformTags, Defined: response.DefinedTags}}
	for _, rule := range response.IngressSecurityRules {
		list.Rules = append(list.Rules, ingressRule(rule))
	}
	for _, rule := range response.EgressSecurityRules {
		list.Rules = append(list.Rules, egressRule(rule))
	}
	return list, nil
}

func updateDetails(rules []nsg.Rule, tags ociresource.Tags) core.UpdateSecurityListDetails {
	// Empty, non-nil slices: a nil slice is omitted from the request body
	// and would leave that direction's rules in place.
	details := core.UpdateSecurityListDetails{IngressSecurityRules: []core.IngressSecurityRule{},
		EgressSecurityRules: []core.EgressSecurityRule{}, FreeformTags: maps.Clone(tags.Freeform), DefinedTags: tags.Defined}
	for _, rule := range rules {
		tcp, udp := nsg.PortOptions(rule)
		var description *string
		if rule.Description != "" {
			description = new(rule.Description)
		}
		if rule.Direction == nsg.DirectionIngress {
			details.IngressSecurityRules = append(details.IngressSecurityRules, core.IngressSecurityRule{
				Protocol: new(rule.Protocol), Source: new(rule.Peer),
				SourceType:  core.IngressSecurityRuleSourceTypeEnum(rule.EffectivePeerType()),
				IsStateless: new(rule.Stateless), TcpOptions: tcp, UdpOptions: udp, Description: description})
			continue
		}
		details.EgressSecurityRules = append(details.EgressSecurityRules, core.EgressSecurityRule{
			Protocol: new(rule.Protocol), Destination: new(rule.Peer),
			DestinationType: core.EgressSecurityRuleDestinationTypeEnum(rule.EffectivePeerType()),
			IsStateless:     new(rule.Stateless), TcpOptions: tcp, UdpOptions: udp, Description: description})
	}
	return details
}

func (a sdkAPI) UpdateList(ctx context.Context, id, etag string, rules []nsg.Rule, tags ociresource.Tags) error {
	_, err := a.network.UpdateSecurityList(ociclient.RequestContext(ctx), core.UpdateSecurityListRequest{SecurityListId: new(id), IfMatch: new(etag),
		UpdateSecurityListDetails: updateDetails(rules, tags)})
	if err != nil {
		return fmt.Errorf("update OCI security list: %w", err)
	}
	return nil
}

