func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

func (f *Factory) Network() (core.VirtualNetworkClient, error) {
	client, err := core.NewVirtualNetworkClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNetwork)
	return client, nil
}

func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func readCancellationConfigured(dispatcher common.HTTPRequestDispatcher) bool {
	switch dispatcher := dispatcher.(type) {
	case readDispatcher:
		return true
	case *instrumentedDispatcher:
		return readCancellationConfigured(dispatcher.next)
	default:
		return false
	}
}

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

func RetryPolicy(options RetryOptions) common.RetryPolicy {
	options = options.normalized()
	return common.NewRetryPolicy(options.MaxAttempts, ShouldRetry, func(response common.OCIOperationResponse) time.Duration {
		return retryDelay(options, response)
	})
}

// IdempotentPutRetryPolicy is RetryPolicy that also replays PUT on 5xx. Use
// it only for request-level policies on writes the caller has made idempotent,
// such as content-addressed multipart part uploads whose commit refuses to
// overwrite (If-None-Match: *).
func IdempotentPutRetryPolicy(options RetryOptions) common.RetryPolicy {
	options = options.normalized()
	return common.NewRetryPolicy(options.MaxAttempts, func(response common.OCIOperationResponse) bool {
		return shouldRetry(response, func(request *http.Request) bool {
			return (request != nil && request.Method == http.MethodPut) || replayable(request)
		})
	}, func(response common.OCIOperationResponse) time.Duration {
		return retryDelay(options, response)
	})
}

// ShouldRetry classifies one attempt under the policy documented on RetryPolicy.
func ShouldRetry(response common.OCIOperationResponse) bool {
	return shouldRetry(response, replayable)
}

func shouldRetry(response common.OCIOperationResponse, replayable func(*http.Request) bool) bool {
	if ctx := readOperationContext(response); ctx != nil && ctx.Err() != nil {
		return false
	}
	status, request := responseStatus(response)
	if response.Error == nil {
		return false
	}
	if status == 0 {
		if serviceErr, ok := common.IsServiceError(response.Error); ok {
			status = serviceErr.GetHTTPStatusCode()
		}
	}
	if status == http.StatusTooManyRequests {
		return true
	}
	if !replayable(request) {
		return false
	}
	if status >= 500 && status != http.StatusNotImplemented && status < 600 {
		return true
	}
	if status == 0 {
		cause := response.Error
		for {
			failure, ok := errors.AsType[*readTransportError](cause)
			if !ok {
				break
			}
			cause = failure.err
		}
		return common.IsNetworkError(cause) || errors.Is(cause, io.EOF) ||
			errors.Is(cause, io.ErrUnexpectedEOF)
	}
	return false
}

func responseStatus(response common.OCIOperationResponse) (int, *http.Request) {
	var raw *http.Response
	if response.Response != nil {
		raw = response.Response.HTTPResponse()
	}
	if raw != nil {
		return raw.StatusCode, raw.Request
	}
	return 0, transportRequest(response.Error)
}

// transportRequest recovers the method of an attempt that failed before any
// HTTP response existed. The SDK then leaves the raw response nil, but
// net/http reports the method in the *url.Error it returns. The synthetic
// request carries only the method, so a POST is never treated as carrying a
// retry token and stays non-replayable.
func transportRequest(err error) *http.Request {
	var urlErr *url.Error
	if !errors.As(err, &urlErr) {
		return nil
	}
	method := strings.ToUpper(strings.TrimSpace(urlErr.Op))
	if method == "" {
		return nil
	}
	return &http.Request{Method: method, Header: http.Header{}}
}

// replayable reports whether repeating request cannot duplicate an effect.
// An unknown request is not replayable.
func replayable(request *http.Request) bool {
	if request == nil {
		return false
	}
	switch request.Method {
	case http.MethodGet, http.MethodHead:
		return true
	case http.MethodPost:
		return strings.TrimSpace(request.Header.Get("opc-retry-token")) != ""
	default:
		return false
	}
}

func defaultHTTPDispatcher() http.Client {
	var httpClient http.Client
	refreshInterval := getCustomCertRefreshInterval()
	if refreshInterval <= 0 {
		Debug("Custom cert refresh has been disabled")
	}
	var tp = &OciHTTPTransportWrapper{
		RefreshRate:       time.Duration(refreshInterval) * time.Minute,
		TLSConfigProvider: GetTLSConfigTemplateForTransport(),
	}

	// Set client timeout to default or value set in environment variable
	clientTimeout := defaultTimeout
	if customTimeout := os.Getenv(CustomClientTimeoutEnvVar); customTimeout != "" {
		if timeInSeconds, err := strconv.Atoi(customTimeout); err != nil || timeInSeconds < 0 {
			Logf("WARNING: %s set but could not be converted to a postive integer", CustomClientTimeoutEnvVar)
		} else {
			Debugf("Using custom client timeout of %s seconds", customTimeout)
			clientTimeout = time.Duration(timeInSeconds) * time.Second
		}
	}

	// Create the underlying HTTP client
	httpClient = http.Client{
		Timeout:   clientTimeout,
		Transport: tp,
	}
	return httpClient
}

func defaultBaseClient(provider KeyProvider) BaseClient {
	dispatcher := defaultHTTPDispatcher()
	signer := DefaultRequestSigner(provider)
	return newBaseClient(signer, &dispatcher)
}

// DefaultBaseClientWithSigner creates a default base client with a given signer
func DefaultBaseClientWithSigner(signer HTTPRequestSigner) BaseClient {
	dispatcher := defaultHTTPDispatcher()
	return newBaseClient(signer, &dispatcher)
}

// NewClientWithConfig Create a new client with a configuration provider, the configuration provider
// will be used for the default signer as well as reading the region
// This function does not check for valid regions to implement forward compatibility
func NewClientWithConfig(configProvider ConfigurationProvider) (client BaseClient, err error) {
	var ok bool
	if ok, err = IsConfigurationProviderValid(configProvider); !ok {
		err = fmt.Errorf("can not create client, bad configuration: %w", err)
		return
	}

	client = defaultBaseClient(configProvider)

	if authConfig, e := configProvider.AuthType(); e == nil && authConfig.OboToken != nil {
		Debugf("authConfig's authType is %s", authConfig.AuthType)
		signOboToken(&client, *authConfig.OboToken, configProvider)
	}

	return
}

func (client BaseClient) CallWithDetails(ctx context.Context, request *http.Request, details ClientCallDetails) (response *http.Response, err error) {
	Debugln("Attempting to call downstream service")
	request = request.WithContext(ctx)

	if client.ociIncludeRequestTelemetryDataEnabled {
		if details.ServiceName != "" {
			request.Header.Set("x-oci-service-name", details.ServiceName)
		}
		if details.ServiceName != "" {
			request.Header.Set("x-oci-operation-id", details.OperationName)
		}
	}

	err = client.prepareRequest(request)
	if err != nil {
		return
	}
	//Intercept
	err = client.intercept(request)
	if err != nil {
		return
	}
	//Sign the request
	err = details.Signer.Sign(request)
	if err != nil {
		return
	}

	//Execute the http request
	if ociGoBreaker := client.Configuration.CircuitBreaker; ociGoBreaker != nil {
		resp, cbErr := ociGoBreaker.Cb.Execute(func() (interface{}, error) {
			return client.httpDo(request)
		})
		if httpResp, ok := resp.(*http.Response); ok {
			if httpResp != nil && httpResp.StatusCode != 200 {
				if failure, ok := IsServiceError(cbErr); ok {
					ociGoBreaker.AddToHistory(resp.(*http.Response), failure)
				}
			}
		}
		if cbErr != nil && IsCircuitBreakerError(cbErr) {
			cbErr = getCircuitBreakerError(request, cbErr, ociGoBreaker)
		}
		if _, ok := resp.(*http.Response); !ok {
			return nil, cbErr
		}
		return resp.(*http.Response), cbErr
	}
	return client.httpDo(request)
}

// IsRefreshableAuthType validates if a signer is from a refreshable config provider
func (client BaseClient) IsRefreshableAuthType() bool {
	if signer, ok := client.Signer.(ociRequestSigner); ok {
		if provider, ok := signer.KeyProvider.(RefreshableConfigurationProvider); ok {
			return provider.Refreshable()
		}
	}
	return false
}

func (client BaseClient) httpDo(request *http.Request) (response *http.Response, err error) {

	//Copy request body and save for logging
	dumpRequestBody := ioutil.NopCloser(bytes.NewBuffer(nil))
	if request.Body != nil && !checkBodyLengthExceedLimit(request.ContentLength) {
		if dumpRequestBody, request.Body, err = drainBody(request.Body); err != nil {
			dumpRequestBody = ioutil.NopCloser(bytes.NewBuffer(nil))
		}
	}
	IfDebug(func() {
		logRequest(request, Debugf, verboseLogging)
	})

	//Execute the http request
	response, err = client.HTTPClient.Do(request)

	if err != nil {
		IfInfo(func() {
			Logf("%v\n", err)
		})
		return response, err
	}

	err = checkForSuccessfulResponse(response, &dumpRequestBody)
	return response, err
}
